"""
    Split into kernel variables and not.

    :param var_couple: var-value pair.
    :param count: number of variable to put into the kernel.
    :type count: int
    :return: all the variable in the kernel (i.e. count vars).
    :rtype: list
    """
def split_kernel_vars(var_couple: Any, count: Any) -> object {
    var_couple.sort(key=lambda (x: Any) { -x[1]; });
    head = var_couple[:count];
    kernel = [n for (n, i) in head];
    return kernel;
}

"""
    Automatically sets the "TIMED_APPEND" App Configuration variable automatically to "TRUE" if
    the "append" option is enabled and the cardinality parameter (if given) is set to "one".

    :param config: Configuration dictionary (the one that gets exported to local.settings.json).
    :param extra_config: Dictionary configuring the additional options passed by user in generator_config.json.
    :param app_type: Application type.
    :param app_path: Path to the output folder for the Function App.
    :return: The local.settings.json dictionary currently being formed.
    """
def ensure_timed_append_if_cardinality_one(
    config: Any, extra_config: Any, app_type: Any, app_path: Any
) -> object {
    if (
        (extra_config["append"].lower() == "true")
        and ("cardinality" in extra_config)
        and (extra_config["cardinality"].lower() == "one")
    ) {
        config["Values"]["TIMED_APPEND"] = "TRUE";
    }
    return config;
}

""" Calculate average heart rate after specified date

    This function first sums all of the heart rates after the specified date.
    It then divides the summed heart rates by the total number of heart rate
    entries. The result is the sum of the heart rates after the entered time.

    :param hrs_after_time: a list of heart rate values that were entered after
    the specified time ("heart_rate_average_since")

    :returns: an integer indicating the average heart rate of the patient after
    a certain date
    """
def calculate_average_since(hrs_after_time: Any) -> object {
    total_entries = len(hrs_after_time);
    average_since = sum(hrs_after_time) / total_entries;
    return average_since;
}

